import more_itertools as mi

# eager TypeError, no iteration at all
class Boom:
    def __iter__(self):
        raise RuntimeError('touched!')
for n in (True, False, 2.0, 2.5, '2', -1.0, 2j):
    try:
        mi.chunked(Boom(), n)
    except TypeError as e:
        print(repr(n), 'TypeError:', e)
    else:
        print(repr(n), 'NO ERROR!')

# lazily-consumed source untouched after TypeError
it = iter([1, 2, 3])
try:
    mi.chunked(it, 1.5)
except TypeError:
    pass
print('untouched:', next(it))

# preserved semantics
print(list(mi.chunked([], None)), list(mi.chunked([1,2,3], None)))
print(list(mi.chunked([1,2,3], 0)))
try:
    mi.chunked([1], -1)
except ValueError as e:
    print('ValueError:', e)
try:
    mi.chunked([1], None, strict=True)
except ValueError as e:
    print('ValueError:', e)
EOF

