python3 -c "
from boltons.iterutils import get_path, PathAccessError
root = {'a': {'b': {'c': [[1], [2], [3]]}}}
# 1) missing key in tuple path
try: get_path(root, ('a','x','c'))
except PathAccessError as e: print('1:', repr(e))
# 2) index error, tuple path
try: get_path(root, ('a','b','c',5,0))
except PathAccessError as e: print('2:', repr(e))
# 3) dotted string path -> list path, numeric seg coercion
try: get_path(root, 'a.b.c.5.0')
except PathAccessError as e: print('3:', repr(e))
# 4) string index fallback to int for lists
print('4:', get_path({'key': ['test']}, 'key.0'), get_path({'key': ['test']}, ('key','0')))
# 5) non-indexable parent
try: get_path({'a': 1}, ('a','b'))
except PathAccessError as e: print('5:', repr(e))
# 6) iterable but non-subscriptable
try: get_path({'a': {1,2}}, ('a','b'))
except PathAccessError as e: print('6:', repr(e))
# 7) root not indexable
try: get_path(5, ('a',))
except PathAccessError as e: print('7:', repr(e))
"

